#include <bits/stdc++.h>
using namespace std;
int main(){int n,m;cin>>n>>m;vector<vector<int>>a(n,vector<int>(m));for(auto&r:a)for(int&x:r)cin>>x;int top=0,bottom=n-1,left=0,right=m-1;while(top<=bottom&&left<=right){for(int j=left;j<=right;j++)cout<<a[top][j]<<' ';top++;for(int i=top;i<=bottom;i++)cout<<a[i][right]<<' ';right--;if(top<=bottom){for(int j=right;j>=left;j--)cout<<a[bottom][j]<<' ';bottom--;}if(left<=right){for(int i=bottom;i>=top;i--)cout<<a[i][left]<<' ';left++;} }cout<<'\n';}